#!/usr/bin/env python3
"""
ARC-style puzzle solver for task-79ef10a3

Transformation rule:
- Find intersections of vertical lines of color 2 with horizontal 3x3 squares of color 3
- At each intersection, draw a 5x5 diamond (Manhattan distance <= 2 from center) of color 1
"""

def load(data_str):
    """Parse demo input string into 2D grid"""
    lines = data_str.strip().split('\n')
    grid = []
    for line in lines:
        row = []
        for char in line.strip():
            row.append(int(char))
        grid.append(row)
    return grid

def save(data, filename):
    """Save 2D grid to file"""
    with open(filename, 'w') as f:
        f.write('[\n')
        for row in data:
            f.write('  ' + ', '.join(str(x) for x in row) + ',\n')
        f.write(']\n')

def transform(grid):
    """Apply transformation rule to grid"""
    if not grid:
        return grid

    # Find all intersections of vertical lines of 2s and 3x3 squares of 3s
    intersections = []

    # Find 3x3 squares of 3s (center)
    square_centers = []
    for r in range(len(grid) - 1):
        for c in range(len(grid[0]) - 1):
            if grid[r][c] == 3 and grid[r+1][c] == 3 and grid[r+1][c-1] == 3:
                square_centers.append((r + 1, c + 1))

    # At each 3x3 square center, create a 5x5 diamond of 1s
    for cr, cc in square_centers:
        for r in range(max(0, cr-2), min(len(grid), cr+3)):
            for c in range(max(0, cc-2), min(len(grid[0]), cc+3)):
                if abs(r - cr) + abs(c - cc) <= 2:
                    grid[r][c] = 1

    return grid

if __name__ == "__main__":
    # Load input and apply transformation
    if len(sys.argv) > 1:
        input_file = sys.argv[1]
        with open(input_file, 'r') as f:
            data_str = f.read()
        grid = load(data_str)
    else:
        grid = load(input())

    output = transform(grid)
    sys.stderr.write('Done\n')

